    '.forge-reader-intro > summary::before { content: "▸  "; color: var(--gold, #d4a55a); display: inline-block; transition: transform 120ms ease; }',
    '.forge-reader-intro[open] > summary::before { content: "▾  "; }',
    '.forge-reader-intro-body {',
